      byId("schoolIdentitySave").onclick=async()=>{const form=byId("schoolIdentityForm"),button=byId("schoolIdentitySave"),normalizeAddress=name=>{const input=form.elements.namedItem(name);if(!input)return;const raw=String(input.value||"").trim();input.value=raw&&!/^[a-z][a-z0-9+.-]*:\/\//i.test(raw)?"https://"+raw:raw;};normalizeAddress("website");normalizeAddress("verification_base_url");if(!form.reportValidity())return;button.disabled=true;try{const payload=formValues(form);if(!brandingEnabled){delete payload.primary_colour;delete payload.accent_colour;delete payload.report_body_font;delete payload.report_body_font_size;}await api().updateSchoolSettings(payload);showMessage("schoolIdentityMessage","School identity saved successfully.","success");notify("School identity saved");}catch(e){showMessage("schoolIdentityMessage",friendly(e));}finally{button.disabled=false;}};
      byId("schoolLogoSave").onclick=async()=>{const input=byId("schoolLogoFile"),file=input?.files?.[0],button=byId("schoolLogoSave"),msg=byId("schoolLogoMessage");if(!file){notify("Select a logo","Choose a PNG, JPEG, or WebP school logo first.","warning");return;}button.disabled=true;try{const blob=await normaliseOfficialSchoolLogo(file),normalised=new File([blob],"school-logo.png",{type:"image/png",lastModified:Date.now()}),uploaded=await api().uploadFile(normalised,"school-branding"),result=await certified("set_school_logo_reference",{target_logo_url:uploaded.objectKey});if(input)input.value="";clearLogoPreviewUrl();const refreshed=await api().bootstrap();window.EdusentiaShell.state.boot=refreshed;await window.EdusentiaShell?.applyTenantBrandLogo?.(refreshed.tenant||{});msg.textContent=result?.message||"Official school logo updated successfully.";msg.dataset.kind="success";msg.classList.remove("hidden");notify("Official school logo saved","The new print-clear logo is active for future official school documents.","success");await renderSettings();}catch(e){msg.textContent=friendly(e);msg.dataset.kind="error";msg.classList.remove("hidden");notify("Logo not saved",friendly(e),"error");}finally{button.disabled=false;}};
      byId("schoolLogoReset").onclick=async()=>{if(!await window.EdusentiaConfirm("Use the original school logo embedded in this licensed package for future official documents? Previous uploaded logo files remain retained for historical reproducibility.",{title:"Restore package logo",confirmLabel:"Restore logo",kind:"primary"}))return;const button=byId("schoolLogoReset");button.disabled=true;try{await certified("set_school_logo_reference",{target_logo_url:"assets/school-logo.png"});clearLogoPreviewUrl();const refreshed=await api().bootstrap();window.EdusentiaShell.state.boot=refreshed;await window.EdusentiaShell?.applyTenantBrandLogo?.(refreshed.tenant||{});notify("Package logo restored","Future official documents use the original package logo.");await renderSettings();}catch(e){notify("Logo not restored",friendly(e),"error");}finally{button.disabled=false;}};
