      const chooseTemplate=async()=>{const key=String(designRange?.value||""),file=designFile?.files?.[0],button=designUpload;if(!key){notify("Choose a class range","Select the class range that will use this report-card design.","warning");return;}if(!file){notify("Choose a template","Select a PDF or DOCX report-card design first.","warning");return;}const extension=String(file.name||"").split(".").pop().toLowerCase(),mime=extension==="pdf"?"application/pdf":extension==="docx"?"application/vnd.openxmlformats-officedocument.wordprocessingml.document":"";if(!mime){notify("Template not uploaded","Only PDF and DOCX files are accepted.","error");return;}if(file.size<=0||file.size>20*1024*1024){notify("Template not uploaded","The template file must be between 1 byte and 20 MB.","error");return;}button.disabled=true;const priorLabel=button.textContent;button.textContent="Uploading";try{const uploaded=await api().uploadFile(file,"report-card-templates",{subfolder:key});await certified("save_report_card_template",{target_range_key:key,target_storage_path:uploaded.objectKey,target_original_name:file.name,target_mime_type:mime,target_file_size:file.size,target_checksum:await sha256(file)});notify("Report-card design assigned",rangeLabels[key]+" now uses "+file.name+".");await renderSettings();}catch(e){notify("Template not saved",friendly(e),"error");}finally{button.disabled=false;button.textContent=priorLabel;}};
      designUpload?.addEventListener("click",chooseTemplate);
      byId("content").querySelectorAll("[data-template-download]").forEach(b=>b.onclick=async()=>{const item=templateByRange(b.dataset.templateDownload);if(!item?.storage_path)return;try{downloadBlob(item.original_name||"report-template",await api().downloadFile(item.storage_path));}catch(e){notify("Template not downloaded",friendly(e),"error");}});
